export interface UpdateRouteData {
  name?: string | null;
  /** Route settings. `track_opens` and `track_clicks` apply to transactional and broadcast routes when email tracking is available. `generate_plaintext_fallback` opts in to generated plaintext fallbacks for HTML-only outbound messages; customer-provided plaintext is always preserved. `suppress_auto_responders` adds outbound headers that suppress auto-responders. `suppress_disposable_recipients` skips matching recipients for each message without adding them to suppression lists. `tls` controls whether TLS is opportunistic or enforced. `disable_hosted_unsubscribe` applies to broadcast routes when enabled for the team. `redact_email_content` requires email redaction access */
  settings?: UpdateRouteSettingsData | null;
  /** Inbound route settings. Only accepted for inbound routes */
  inbound_settings?: UpdateRouteInboundSettingsData | null;
  inbound_domain?: string | null;
  inbound_spam_threshold?: number | null;
  attachment_delivery?: AttachmentDelivery | null;
}

